def parse_ini(text):
    """Sections, keys and values of INI text. See TASK.md."""
    result = {}
    current_section = None
    current_key = None  # last key set in current section (for continuations)

    for i, raw in enumerate(text.split("\n")):
        line = raw[:-1] if raw.endswith("\r") else raw
        N = i + 1
        stripped = line.strip()

        # Rule 2: empty/whitespace-only lines are skipped.
        if stripped == "":
            continue
        # Rule 2/5: comments start only when first non-whitespace char is ; or #.
        if stripped[0] in ";#":
            continue

        # Rule 7: a line starting with space/tab (and not blank/comment)
        # continues the value of the previous key.
        if line[0] in " \t":
            if current_section is None or current_key is None:
                raise ValueError(f"line {N}: continuation with no preceding key")
            result[current_section][current_key] += "\n" + stripped
            continue

        # Rule 3: [name] on a line of its own starts a section.
        if stripped.startswith("[") and stripped.endswith("]"):
            name = stripped[1:-1].strip()
            if name == "":
                raise ValueError(f"line {N}: empty section name")
            current_section = name
            current_key = None  # a section header ends continuation reach
            if name not in result:
                result[name] = {}
            continue

        # Rule 4: key = value (split at the first '=').
        if "=" in line:
            idx = line.index("=")
            key = line[:idx].strip().lower()
            value = line[idx + 1:].strip()
            if key == "":
                raise ValueError(f"line {N}: empty key")
            if current_section is None:
                current_section = ""
                result[""] = {}
            result[current_section][key] = value
            current_key = key
            continue

        # Rule 10: anything else is an error.
        raise ValueError(f"line {N}: bad line")

    # Rule 6: the "" section appears only when it has at least one key.
    if "" in result and not result[""]:
        del result[""]
    return result
